import ast, json, hashlib
from pathlib import Path
r=json.load(open('runtime_context.json'));p=json.load(open('proposal.json'))
def validate(x,s,path='"'$'"'):
 typ=s.get('type'); types={'object':dict,'array':list,'string':str,'boolean':bool}
 if typ in types: assert isinstance(x,types[typ]),(path,'type',typ)
 if 'enum' in s: assert x in s['enum'],(path,'enum')
 if 'const' in s: assert x==s['const'],(path,'const')
 if isinstance(x,dict):
  assert set(s.get('required',[]))<=set(x),(path,'required')
  props=s.get('properties',{})
  if s.get('additionalProperties') is False: assert set(x)<=set(props),(path,'extra keys')
  for k,v in x.items():
   if k in props:validate(v,props[k],path+'.'+k)
 if isinstance(x,list):
  assert len(x)>=s.get('minItems',0),(path,'minItems')
  if 'items' in s:
   for n,v in enumerate(x):validate(v,s['items'],path+f'[{n}]')
 if isinstance(x,str): assert len(x)>=s.get('minLength',0),(path,'minLength')
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
allowed=set(r['context']['allowed_observation_ids'])
assert set(p['study']['evidence_refs'])<=allowed
assert p['parent_trial'] in allowed
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
for v in p['variants']:
 f=Path(v['file']);assert f.name==v['file'] and f.suffix=='.py' and f.is_file()
 tree=ast.parse(f.read_text());compile(tree,str(f),'exec')
 cfg=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
 assert cfg==v['config']
 assert hashlib.sha256(f.read_bytes()).hexdigest() in v['note']
 for n in ast.walk(tree):
  if isinstance(n,ast.Import):assert all(a.name.split('.')[0] in {'math','copy','torch'} for a in n.names)
  elif isinstance(n,ast.ImportFrom):assert n.module.split('.')[0] in {'torch','unirank'}
 for n in ast.walk(tree):
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):assert n.func.id not in {'open','exec','eval','compile','__import__'}
assert {v['role'] for v in p['variants']}<= {'candidate','control'}
assert set(r['context']['latest_knowledge_usage']['retrieved_ids'])<= {x['knowledge_id'] for x in p['knowledge_assessments']}
print('PASS: runtime study schema, evidence/parent IDs, protocol hash, four variant files/configs/hashes/import boundaries and prior knowledge coverage.')
print('No host execution, training, test scoring or package installation was performed.')
print('Proposal SHA256:',hashlib.sha256(Path('proposal.json').read_bytes()).hexdigest())
Path('runtime_context.json').unlink()
PY"

